expected_code:
def solve():
    data = list(range(1, 101))
    n = len(data)
    sorted_data = sorted(data)
    def percentile(p):
        idx = (p / 100) * (n - 1)
        lo = int(idx)
        hi = lo + 1
        if hi >= n:
            return float(sorted_data[-1])
        frac = idx - lo
        return round(sorted_data[lo] + frac * (sorted_data[hi] - sorted_data[lo]), 4)
    return (percentile(2.5), percentile(97.5))

